"<?php\n\nnamespace Tests\\Browser;\n\nuse Tests\\DuskTestCase;\nuse Laravel\\Dusk\\Browser;\nuse App\\Models\\User;\nuse App\\Models\\Manuscript;\n\nclass ManuscriptVerificationTest extends DuskTestCase\n{\n    public function test_verify_manuscript_full_feature_in_chrome()\n    {\n        $this->browse(function (Browser $browser) {\n            $user = User::first() ?? User::factory()->create([\n                'email' => 'admin@test.com',\n                'password' => bcrypt('password'),\n            ]);\n\n            $manuscript = Manuscript::where('title', 'like', '%كليلة%')->first()\n                ?? Manuscript::first();\n\n            $this->assertNotNull($manuscript, \"Manuscript must exist\");\n\n            // 1. Visit Manuscript Show Page\n            $browser->loginAs($user)\n                ->visit(\"/manuscripts/{$manuscript->slug}\")\n                ->waitForText($manuscript->title, 10)\n                ->pause(1500)\n                ->screenshot('ms_verified_1_show');\n\n            // 2. Visit Sandbox (غرفة المعاينة)\n            $browser->visit(\"/dev/manuscripter/{$manuscript->slug}\")\n                ->waitFor('#main-viewer, main', 10)\n                ->pause(2000)\n                ->screenshot('ms_verified_2_sandbox');\n\n            // Verify image src in sandbox\n            $imgSrc = $browser->script(\"\n                const img = document.querySelector('main img, #main-viewer img');\n                return img ? img.src : 'NO_IMG';\n            \")[0];\n\n            echo \"\\n[Dusk Sandbox Image Src]: \" . $imgSrc . \"\\n\";\n            $this->assertNotEquals('NO_IMG', $imgSrc, \"Image should be found in sandbox viewer\");\n            $this->assertNotEmpty($imgSrc, \"Image src should not be empty\");\n\n            // 3. Visit Studio\n            $browser->visit(\"/studio/manuscript/{$manuscript->slug}\")\n                ->waitFor('.tiptap, #split-container', 10)\n                ->pause(2500)\n                ->screenshot('ms_verified_3_studio');\n\n         
